VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling', 2, 'maro2', 1790920647799, 'maro2', 1790920350265, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', 'counseling', 'Create a Rega application, MicroApp, and MicroService specification draft for a counseling reservation system within the Counseling-latest bounded context.', 'CounselingReservation', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest');

VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling-spec', 1, 'maro2', 1790920589526, 'maro2', 1790920350272, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"businessPurpose":"Provide one counseling reservation application for submitting counseling requests, coordinating schedules, confirming appointments, and handling permitted changes or cancellations.","userValue":"Applicants can submit and monitor their own counseling requests, while counseling operators can process requests into valid confirmed appointments without exposing internal coordination information.","expectedOutcome":"A reviewable draft specification for applicant self-service, operator counseling operations, and one cohesive counseling reservation service.","ownerOrganization":null,"targetOrganizations":null,"scope":{"inScopes":["Counseling request submission and applicant-scoped status review","Operator-scoped request processing and scheduling coordination","Responsible operator assignment, candidate time handling, reservation confirmation, pre-start time changes, cancellation, conflict prevention, and processing history"],"outOfScopes":["Authentication and role assignment","Actual communication, notifications, payments, external calendar integration, work schedules, holidays, and user-defined columns","Academy, course, membership, class, attendance, no-show, counseling outcome, and post-counseling closure management"]},"stakeholders":[{"key":"applicant","name":"Applicant","role":"Applicant who submits and monitors a counseling request","goals":["Submit and monitor the applicant''s own counseling request through confirmation or permitted cancellation."],"protectedInterests":["Privacy of the applicant''s request and internal coordination information"]},{"key":"counseling-operator","name":"Counseling Operator","role":"Operator who processes counseling requests and confirms appointments","goals":["Process counseling requests from submission through scheduling coordination and reservation confirmation, with permitted changes and cancellation."],"protectedInterests":["Consistent reservation facts, conflict prevention, and auditable processing"]}],"journey":{"startStepKey":"my-counseling","steps":[{"key":"my-counseling","microAppCode":"mycounseling"},{"key":"counseling-operations","microAppCode":"counselingoperations"}],"transitions":[{"key":"applicant-to-operations","fromStepKey":"my-counseling","toStepKey":"counseling-operations","flowType":"NORMAL","condition":"The submitted counseling request is available for operator processing."},{"key":"operations-to-applicant-review","fromStepKey":"counseling-operations","toStepKey":"my-counseling","flowType":"NORMAL","condition":"The applicant returns to review the current status or confirmed appointment."}],"endConditions":["The applicant can review a confirmed appointment or permitted cancellation result.","A counseling request remains consistent with its processing history and reservation facts."]},"commonContexts":[{"key":"counseling-request","name":"Counseling Request","description":"The counseling request and its applicant-visible processing and reservation facts.","source":"Document DR-COUNSEL business concepts"},{"key":"reservation-coordination","name":"Reservation Coordination","description":"Operator-managed assignment, candidate time, confirmed appointment, and coordination notes with candidate and confirmed meanings kept distinct.","source":"Document P02-P04 and C3-C5"}],"policies":[{"key":"applicant-privacy","category":"Access and disclosure","name":"Applicant Privacy","statement":"Applicants may access only their own request and may not see internal candidate times, contact notes, or operator account identifiers."},{"key":"reservation-consistency","category":"Business integrity","name":"Reservation Consistency","statement":"Confirmed reservations must prevent overlapping appointments for the same responsible operator, and failed changes must preserve the original reservation."}],"qualityRequirements":[{"key":"accessible-small-screen-use","category":"Accessibility","expectation":"Applicant and operator work must remain usable with keyboard interaction and on narrow screens.","measure":"Review against the source accessibility and small-screen acceptance requirements."},{"key":"recoverable-processing","category":"Recovery","expectation":"Processing progress, failure reasons, and next actions must be communicated without silently opening details or duplicating work.","measure":"Review against source requirements Q01-Q03."}],"supplementarySpec":null,"acceptanceCriteria":[{"key":"applicant-self-service","statement":"An authenticated applicant can submit, review, and cancel only the applicant''s own counseling request when permitted."},{"key":"operator-processing","statement":"An authorized counseling operator can coordinate and confirm a request while preserving lifecycle, conflict, access, and audit guarantees."},{"key":"single-service-boundary","statement":"The counseling reservation responsibility remains within one cohesive MicroService rather than being split by role, screen, or capability."}],"openIssues":[{"key":"operating-owner","question":"Which organization or operational owner will be responsible for the counseling reservation service?","decision":null,"resolved":false,"blocking":false},{"key":"operating-conditions","question":"Should the proposed appointment duration, operating hours, timezone, and start-time rules be confirmed as the operational policy?","decision":null,"resolved":false,"blocking":false}]}', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling', 'Approved', '0.1.0');

VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-ms:counseling', 0, 'maro2', 1790920350278, 'maro2', 1790920350278, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', 'counseling', 'Own counseling request intake, applicant-scoped and operator-scoped request views, scheduling coordination, responsible operator assignment, candidate time handling, confirmed appointment reservation, pre-start time changes, cancellation, conflict prevention, lifecycle transitions, processing history, and consistency of reservation facts.', 'LoB', 'Counseling', 'Business', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest', NULL);

VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-ms:counseling-drama-spec', 1, 'maro2', 1790920575912, 'maro2', 1790920350285, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"businessPurpose":"Own the counseling request and reservation facts needed to accept requests, coordinate schedules, confirm appointments, support permitted changes or cancellations, and preserve consistent processing history.","ownerOrganization":null,"responsibilityBoundary":{"coreResponsibilities":["Own counseling request intake, applicant-scoped and operator-scoped request views, scheduling coordination, responsible operator assignment, candidate time handling, confirmed appointment reservation, pre-start time changes, cancellation, conflict prevention, lifecycle transitions, processing history, and consistency of reservation facts."],"nonResponsibilities":["Authentication and role assignment are owned by the execution platform.","Actual phone or message communication is outside the service; only operator notes are recorded.","Academy and course management, membership registration, classes, sessions, seats, attendance, no-show processing, counseling outcomes, and post-counseling closure are excluded.","External notifications, payments, external calendar integration, work schedules, holidays, and user-defined columns are excluded.","The service does not create a separate member, organization, or operator identity model."]},"stakeholders":[{"key":"applicant","name":"Applicant","role":"Applicant who submits, reviews, and may cancel the applicant''s own counseling request","goals":["Submit a counseling request, view the applicant''s own status and confirmed appointment, and cancel the applicant''s own request when permitted."],"protectedInterests":["Privacy of the applicant''s request and restricted disclosure of internal coordination information"]},{"key":"counseling-operator","name":"Counseling Operator","role":"Operator who views and processes counseling requests","goals":["View and process all counseling requests, assign an operator, manage coordination information and notes, confirm reservations, change confirmed times before the appointment starts, and cancel requests when permitted."],"protectedInterests":["Consistent reservation facts, conflict prevention, concurrency safety, and processing history"]}],"businessConcepts":[{"key":"counseling-request","name":"Counseling Request","definition":"A counseling request connecting applicant information, request content, consent, requested time, processing meaning, and reservation facts owned by this service.","identityCriteria":"The service-owned request that represents one applicant counseling request and its processing history.","ownershipType":"OWNED"},{"key":"reservation-coordination","name":"Reservation Coordination","definition":"Operator-managed coordination information including responsible operator, candidate time, contact notes, and the distinction between candidate and confirmed appointment meanings.","identityCriteria":"Coordination information associated with a counseling request.","ownershipType":"OWNED"},{"key":"confirmed-appointment","name":"Confirmed Appointment","definition":"The confirmed counseling appointment made available to the applicant after responsibility, time validity, and overlap checks succeed.","identityCriteria":"The confirmed appointment associated with a counseling request.","ownershipType":"OWNED"},{"key":"processing-history","name":"Processing History","definition":"The record of meaningful processing changes, including state, assignment, candidate or confirmed time, cancellation, and coordination-note changes.","identityCriteria":"Historical facts associated with processing a counseling request.","ownershipType":"OWNED"},{"key":"authenticated-account","name":"Authenticated Account","definition":"An identity and role fact supplied by the execution platform for access decisions and operator assignment references.","identityCriteria":"The platform-provided account identity referenced by the service.","ownershipType":"REFERENCE"}],"capabilities":[{"key":"submit-counseling-request","name":"Submit Counseling Request","capabilityType":"COMMAND","businessGoal":"Accept one valid counseling request with required applicant information, requested time, and privacy consent while preventing an active duplicate request.","stakeholderKeys":["applicant"],"trigger":"An authenticated applicant submits the required counseling request information and consent.","preconditions":["The requester is authenticated as an applicant.","Required request information and privacy consent are present.","The applicant has no other active counseling request according to the applicable active-request rule."],"businessResults":["One counseling request is accepted without creating an active duplicate.","The request is available for later applicant review and operator processing."],"domainEventKeys":["counseling-request-submitted"],"businessConceptKeys":["counseling-request","processing-history"]},{"key":"view-own-counseling-request","name":"View Own Counseling Request","capabilityType":"QUERY","businessGoal":"Provide an authenticated applicant with the applicant''s own request status, confirmed appointment information, and permitted cancellation information without exposing internal coordination data.","stakeholderKeys":["applicant"],"trigger":"An authenticated applicant requests the applicant''s own counseling request information.","preconditions":["The requester is authenticated as the applicant associated with the request."],"businessResults":["The applicant receives permitted request status, confirmed appointment information, and cancellation information without internal candidate or coordination details."],"domainEventKeys":[],"businessConceptKeys":["counseling-request","confirmed-appointment"]},{"key":"view-counseling-requests","name":"View Counseling Requests","capabilityType":"QUERY","businessGoal":"Provide an authorized operator with the counseling request information needed to process the full request workload.","stakeholderKeys":["counseling-operator"],"trigger":"An authorized counseling operator requests the counseling workload.","preconditions":["The requester has the operator role supplied by the execution platform."],"businessResults":["The operator receives the request information needed for permitted processing, including the appropriate processing view."],"domainEventKeys":[],"businessConceptKeys":["counseling-request","reservation-coordination","confirmed-appointment","processing-history"]},{"key":"manage-scheduling-coordination","name":"Manage Scheduling Coordination","capabilityType":"COMMAND","businessGoal":"Save the assigned operator, candidate time, and contact notes used to coordinate a counseling request without treating a candidate time as a confirmed reservation.","stakeholderKeys":["counseling-operator"],"trigger":"An authorized operator saves coordination information for a counseling request.","preconditions":["The requester has operator processing authority.","A candidate time is not treated as a confirmed reservation.","A candidate time requires a responsible operator when the applicable coordination rule requires one."],"businessResults":["Coordination information is saved with candidate and confirmed meanings kept distinct.","The processing history records the meaningful coordination change."],"domainEventKeys":["scheduling-coordination-updated"],"businessConceptKeys":["counseling-request","reservation-coordination","processing-history"]},{"key":"transition-counseling-request","name":"Transition Counseling Request","capabilityType":"COMMAND","businessGoal":"Apply only permitted lifecycle transitions between submitted, scheduling coordination, and confirmed reservation states, while preserving the original state when validation fails.","stakeholderKeys":["counseling-operator"],"trigger":"An authorized operator requests a permitted counseling request transition.","preconditions":["The requester has operator processing authority.","The requested transition is permitted by the counseling request lifecycle policy."],"businessResults":["A permitted transition is applied and recorded.","An invalid transition leaves the original business meaning unchanged and provides a failure reason."],"domainEventKeys":["counseling-request-transitioned"],"businessConceptKeys":["counseling-request","processing-history"]},{"key":"confirm-counseling-reservation","name":"Confirm Counseling Reservation","capabilityType":"COMMAND","businessGoal":"Confirm a valid counseling appointment after rechecking the responsible operator, valid time, and overlapping confirmed reservations.","stakeholderKeys":["counseling-operator"],"trigger":"An authorized operator requests confirmation of a coordinated counseling request.","preconditions":["The requester has operator processing authority.","A responsible operator and valid candidate time are available.","The requested time passes current operating and overlap checks."],"businessResults":["A valid counseling appointment becomes confirmed and available for applicant review.","The confirmation and processing history remain consistent."],"domainEventKeys":["counseling-reservation-confirmed"],"businessConceptKeys":["counseling-request","reservation-coordination","confirmed-appointment","processing-history"]},{"key":"change-counseling-time","name":"Change Counseling Time","capabilityType":"COMMAND","businessGoal":"Change a confirmed appointment before its start time to another valid time for the same responsible operator, preserving the original appointment if the change fails.","stakeholderKeys":["counseling-operator"],"trigger":"An authorized operator requests a time change for a confirmed appointment before its start.","preconditions":["The requester has operator processing authority.","The confirmed appointment has not started.","The responsible operator remains the same.","The replacement time passes current validity and overlap checks."],"businessResults":["The confirmed appointment time is changed and the processing history records the change.","If validation fails, the original appointment remains unchanged."],"domainEventKeys":["counseling-time-changed"],"businessConceptKeys":["confirmed-appointment","processing-history"]},{"key":"cancel-counseling-request","name":"Cancel Counseling Request","capabilityType":"COMMAND","businessGoal":"Cancel a permitted counseling request with a required reason, preserve the cancellation history, and release any confirmed appointment exactly once.","stakeholderKeys":["applicant","counseling-operator"],"trigger":"An authorized applicant or operator requests cancellation with a reason.","preconditions":["The requester is authorized for the request scope.","A cancellation reason is provided.","The request is within a permitted cancellation point."],"businessResults":["The request is cancelled with its reason and processing history preserved.","Any confirmed appointment is released once, and repeated cancellation does not create duplicate effects."],"domainEventKeys":["counseling-request-cancelled"],"businessConceptKeys":["counseling-request","confirmed-appointment","processing-history"]}],"dramaRoles":[{"key":"applicant","name":"applicant","abbreviation":"app","description":"Submit a counseling request, view the applicant''s own status and confirmed appointment, and cancel the applicant''s own request when permitted.","roleBasedApiKeys":[],"capabilityGrants":[{"capabilityKey":"submit-counseling-request","accessConditions":["Access is limited to the authenticated applicant''s own request scope."]},{"capabilityKey":"view-own-counseling-request","accessConditions":["Return only the authenticated applicant''s own permitted request information."]},{"capabilityKey":"cancel-counseling-request","accessConditions":["Allow cancellation only for the authenticated applicant''s own request and only when the cancellation policy permits it."]}]},{"key":"counseling-operator","name":"counseling-operator","abbreviation":"cop","description":"View and process all counseling requests, assign an operator, manage coordination information and notes, confirm reservations, change confirmed times before the appointment starts, and cancel requests when permitted.","roleBasedApiKeys":[],"capabilityGrants":[{"capabilityKey":"view-counseling-requests","accessConditions":["The requester has operator authority supplied by the execution platform."]},{"capabilityKey":"manage-scheduling-coordination","accessConditions":["The requester has operator authority and may manage coordination information for the request workload."]},{"capabilityKey":"transition-counseling-request","accessConditions":["The requested transition must be permitted by the counseling request policy."]},{"capabilityKey":"confirm-counseling-reservation","accessConditions":["Confirmation requires current responsibility, time validity, and overlap checks."]},{"capabilityKey":"change-counseling-time","accessConditions":["The appointment must not have started, the responsible operator remains the same, and the replacement time is valid."]},{"capabilityKey":"cancel-counseling-request","accessConditions":["The requester has operator authority and the cancellation policy permits the requested cancellation."]}]}],"roleBasedApis":[],"features":[{"key":"counseling-reservation-management","name":"Counseling Reservation Management","description":"Manage counseling request intake, coordination, confirmation, permitted changes, cancellation, and role-scoped views.","businessPurpose":"Prevent missed requests and conflicting counseling times while giving applicants status visibility and operators a coherent processing workspace.","inScopes":["Counseling request and reservation management","Applicant and operator access views","Processing history and reservation consistency"],"outOfScopes":["Authentication and role assignment","Communication delivery, notifications, payments, external calendars, and post-counseling work"],"capabilityKeys":["submit-counseling-request","view-own-counseling-request","view-counseling-requests","manage-scheduling-coordination","transition-counseling-request","confirm-counseling-reservation","change-counseling-time","cancel-counseling-request"]}],"businessRules":[{"key":"active-request-uniqueness","category":"Intake","name":"Active Request Uniqueness","statement":"Only one active counseling request is allowed per applicant under the defined active-request policy; repeated submission must not create an active duplicate."},{"key":"candidate-is-not-confirmed","category":"Coordination","name":"Candidate Time Is Not Confirmation","statement":"Saving a candidate time does not create a confirmed reservation or occupy confirmed appointment availability."},{"key":"permitted-lifecycle","category":"Lifecycle","name":"Permitted Request Progression","statement":"The normal progression is submission to scheduling coordination to confirmed reservation; reverse, skipped, resumed, and post-confirmation workflow transitions are not introduced."},{"key":"operator-overlap-prevention","category":"Reservation","name":"Operator Overlap Prevention","statement":"Confirmed appointments for the same responsible operator must not overlap, while a candidate time remains non-confirming until reservation confirmation succeeds."},{"key":"pre-start-time-change","category":"Reservation","name":"Pre-Start Time Change","statement":"A confirmed appointment may be changed before its start to another valid time for the same responsible operator; failed changes preserve the original appointment."},{"key":"permitted-cancellation","category":"Cancellation","name":"Permitted Cancellation","statement":"Cancellation requires a reason, is allowed only at permitted points, preserves cancellation history, and releases a confirmed appointment exactly once."},{"key":"role-scoped-disclosure","category":"Access and disclosure","name":"Role-Scoped Disclosure","statement":"Applicants can access only their own permitted request information; internal candidate times, contact notes, and operator account identifiers are not disclosed to applicants."},{"key":"idempotent-processing","category":"Consistency","name":"Idempotent Processing","statement":"Retries of submission, reservation, time change, and cancellation must not create duplicate business effects or duplicate processing history."}],"domainEvents":[{"key":"counseling-request-submitted","name":"Counseling Request Submitted","meaning":"A valid counseling request has been accepted without an active duplicate.","occurrenceCondition":"Submission validation and the active-request rule succeed.","coreFacts":["Counseling request was accepted","Applicant request scope applies"]},{"key":"scheduling-coordination-updated","name":"Scheduling Coordination Updated","meaning":"Operator coordination information was meaningfully updated without confirming a reservation.","occurrenceCondition":"Coordination information is successfully saved.","coreFacts":["Responsible operator or candidate time or coordination note changed","Candidate time remains distinct from confirmed reservation"]},{"key":"counseling-request-transitioned","name":"Counseling Request Transitioned","meaning":"A permitted counseling request lifecycle transition was applied.","occurrenceCondition":"The requested transition passes the lifecycle policy.","coreFacts":["Counseling request processing meaning changed","Transition was recorded in processing history"]},{"key":"counseling-reservation-confirmed","name":"Counseling Reservation Confirmed","meaning":"A counseling appointment was confirmed after current validity and overlap checks.","occurrenceCondition":"Confirmation succeeds with a responsible operator and valid non-conflicting time.","coreFacts":["Confirmed appointment exists","Applicant-visible confirmation is available"]},{"key":"counseling-time-changed","name":"Counseling Time Changed","meaning":"A confirmed appointment was changed before start for the same responsible operator.","occurrenceCondition":"The replacement time passes pre-start, validity, and overlap checks.","coreFacts":["Confirmed appointment time changed","Original appointment was replaced without silent overwrite"]},{"key":"counseling-request-cancelled","name":"Counseling Request Cancelled","meaning":"A permitted counseling request was cancelled with a reason.","occurrenceCondition":"Cancellation authorization, timing, and reason requirements succeed.","coreFacts":["Cancellation reason was recorded","Any confirmed appointment was released once"]}],"collaborations":[{"targetMicroserviceCode":null,"externalParty":"Execution platform","purpose":"Supply authentication and role information for applicant and operator access decisions.","requiredCapabilities":["Authenticated account and role information"],"inputFacts":["Authenticated requester identity","Requester role information"],"requestedActions":["Validate that the requester is authenticated and has the required role"],"expectedResults":["The service either receives sufficient access context or refuses the business operation"],"consumedDomainEventKeys":[],"providedDomainEventKeys":[],"failureHandling":"If authentication or role information is unavailable, the service must not permit the requested business operation."}],"minimumGuarantees":["Failed lifecycle transitions preserve the original business meaning.","Failed time changes preserve the original confirmed appointment.","Applicant disclosure excludes internal candidate times, contact notes, and operator account identifiers.","Retries do not create duplicate business effects or duplicate cancellation releases.","Processing history and reservation facts remain consistent with successful business changes."],"successGuarantees":["Valid requests are accepted without an active duplicate.","Confirmed appointments pass current responsible-operator, validity, and overlap checks.","Permitted cancellations retain their reason and release confirmed appointment availability exactly once.","Applicants can retrieve permitted status and confirmed appointment information.","Meaningful processing changes are preserved in processing history."],"qualityRequirements":[{"key":"accessibility","category":"Accessibility","expectation":"The supported applicant and operator work can be performed with keyboard interaction and on narrow screens.","measure":"Review against source requirements Q02 and related acceptance criteria."},{"key":"recoverability","category":"User experience","expectation":"Progress, failure reasons, and next actions are communicated, duplicate execution is prevented, and failed work can be retried without silent data loss.","measure":"Review against source requirement Q03."},{"key":"concurrency-safety","category":"Consistency","expectation":"Concurrent operator changes must not silently overwrite one another.","measure":"Confirm the downstream design provides an explicit concurrency-control decision."}],"acceptanceCriteria":[{"key":"request-intake","statement":"A valid applicant request is accepted once, and an active duplicate is not created."},{"key":"role-scoped-views","statement":"Applicants see only their own permitted information, while authorized operators can view the processing workload."},{"key":"coordination-separation","statement":"Candidate coordination information can be saved without creating a confirmed reservation."},{"key":"reservation-confirmation","statement":"Confirmation succeeds only when required responsibility, time validity, and overlap checks pass."},{"key":"time-change-preservation","statement":"A failed pre-start time change leaves the original appointment unchanged."},{"key":"cancellation-integrity","statement":"Permitted cancellation records a reason, preserves history, and releases any confirmed appointment once."}],"openIssues":[{"key":"service-owner","question":"Which organization will own and operate the Counseling MicroService?","decision":null,"resolved":false,"blocking":false},{"key":"operating-policy","question":"Should the proposed 30-minute duration, Monday-to-Friday 10:00-17:00 Asia/Seoul operating window, 30-minute start intervals, and 16:30 last start be confirmed?","decision":null,"resolved":false,"blocking":false},{"key":"retry-and-concurrency-design","question":"Which downstream retry identifier and concurrency-control approach should protect idempotency and prevent silent concurrent overwrites?","decision":null,"resolved":false,"blocking":false}]}', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-ms:counseling', 'Approved', '0.1.0');

