VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling-micro-app:counselingoperations-episode-spec', 1, 'maro2', 1790920581383, 'maro2', 1790920350319, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"An authorized counseling operator processes requests in a three-column kanban, coordinates assignment and candidate time, confirms valid reservations, changes confirmed times before start, or cancels requests with a reason.","businessPurpose":"Allow an operator to turn submitted counseling requests into valid confirmed appointments while preserving lifecycle, conflict, access, and audit guarantees.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"An authorized counseling operator has a submitted or in-progress counseling request to process.","businessSubject":"The counseling request workload and its reservation coordination","endConditions":["A valid appointment is confirmed and available for applicant review.","A permitted cancellation is recorded with its reason.","A failed transition or time change leaves the original business meaning unchanged."]},"stakeholders":[{"key":"counseling-operator","name":"Counseling Operator","role":"Operator processing counseling requests and reservations","goals":["Process all counseling requests from submission through scheduling coordination and reservation confirmation, with permitted changes and cancellation."],"protectedInterests":["Consistent reservation facts, conflict prevention, concurrency safety, and processing history"]}],"acts":[{"key":"counseling-operator","name":"counseling-operator","stakeholderKey":"counseling-operator","responsibility":"Process all counseling requests from submission through scheduling coordination and reservation confirmation, with permitted changes and cancellation."}],"useCases":[{"key":"counseling-request-processing","name":"counseling-request-processing","actKey":"counseling-operator","userGoal":"Process a submitted counseling request into a valid reservation by coordinating the responsible operator and time, confirming the appointment, and handling permitted changes or cancellation.","trigger":"The operator selects a submitted or in-progress request for processing.","endConditions":["The request is confirmed with a valid responsible operator and time, or is cancelled with a reason.","Failed transitions and time changes preserve the original request or appointment."],"capabilityNeeds":[{"key":"counseling-request-processing-view-counseling-requests-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"view-counseling-requests","businessPurpose":"View the request workload and processing information.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-processing-manage-scheduling-coordination-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"manage-scheduling-coordination","businessPurpose":"Save responsible operator, candidate time, and coordination notes without confirming a reservation.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-processing-transition-counseling-request-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"transition-counseling-request","businessPurpose":"Apply only permitted counseling request lifecycle transitions.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-processing-confirm-counseling-reservation-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"confirm-counseling-reservation","businessPurpose":"Confirm a valid appointment after current responsibility, time, and overlap checks.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-processing-change-counseling-time-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"change-counseling-time","businessPurpose":"Change a confirmed appointment before start while preserving the original when validation fails.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-processing-cancel-counseling-request-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"cancel-counseling-request","businessPurpose":"Cancel a request when permitted and preserve its reason and history.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"coordination-to-confirmation","fromUseCaseKey":"counseling-request-processing","toUseCaseKey":"counseling-request-processing","flowType":"NORMAL","condition":"The request has an assigned operator, a valid candidate time, and no conflicting confirmed appointment."}],"dramaParticipations":[{"key":"counseling-operator-counseling-participation","microserviceCode":"counseling","stakeholderKey":"counseling-operator","dramaRoleKey":"counseling-operator","accessPurpose":"Process all counseling requests from submission through scheduling coordination and reservation confirmation, with permitted changes and cancellation.","accessConditions":["The operator must have processing authority supplied by the execution platform."]}],"contexts":[{"key":"operator-processing-context","name":"Operator Processing Context","description":"The request workload, coordination information, confirmation facts, and processing history used by an authorized operator.","source":"Document EP-OP and UC-OP-01"}],"eventReactions":null,"policies":[{"key":"operator-processing-separation","category":"Usage","name":"Movement and Detail Separation","statement":"Kanban movement changes processing meaning without automatically opening details; detail editing requires explicit card entry and save."},{"key":"operator-confirmation","category":"Reservation","name":"Confirmation Preconditions","statement":"Reservation confirmation requires a responsible operator, a valid time, and no conflicting confirmed appointment."},{"key":"operator-change-preservation","category":"Consistency","name":"Failed Change Preservation","statement":"A failed transition or time change leaves the original state or appointment unchanged."}],"acceptanceCriteria":[{"key":"operator-kanban","statement":"The operator can view the normal submitted, scheduling coordination, and confirmed reservation workload, with cancellation available separately."},{"key":"operator-coordination","statement":"The operator can save assignment, candidate time, and coordination notes without treating candidate time as a confirmed reservation."},{"key":"operator-confirmation","statement":"The operator can confirm only when required information and current overlap checks succeed."},{"key":"operator-time-change","statement":"The operator can change a confirmed time before start for the same responsible operator, and failed changes preserve the original appointment."},{"key":"operator-cancellation","statement":"The operator can cancel when permitted with a required reason and preserved processing history."}],"openIssues":[],"summaryUseCases":[{"key":"operator-counseling-processing","goal":"Process counseling requests from submission through scheduling coordination and confirmation, with permitted time changes and cancellation.","preconditions":["The operator is authenticated and authorized.","A counseling request is available for processing."],"steps":[{"key":"review-request","roleKey":"counseling-operator","description":"The operator reviews the request workload and selects a request for processing.","useCaseKey":"counseling-request-processing","externalWork":null,"nextSteps":[{"key":"to-coordinate","toStepKey":"coordinate-request","flowType":"NORMAL","condition":"The request requires assignment or candidate time coordination."}]},{"key":"coordinate-request","roleKey":"counseling-operator","description":"The operator separately opens the request details and saves coordination information.","useCaseKey":"counseling-request-processing","externalWork":null,"nextSteps":[{"key":"to-confirm","toStepKey":"confirm-request","flowType":"NORMAL","condition":"The request has a responsible operator, valid candidate time, and no conflicting confirmed appointment."}]},{"key":"confirm-request","roleKey":"counseling-operator","description":"The operator confirms the reservation or receives a failure reason while the original processing meaning remains unchanged.","useCaseKey":"counseling-request-processing","externalWork":null,"nextSteps":[]},{"key":"handle-alternative","roleKey":"counseling-operator","description":"Before start, the operator may change the confirmed time or cancel the request with a reason when permitted.","useCaseKey":"counseling-request-processing","externalWork":null,"nextSteps":[]}],"successResults":["A valid counseling appointment is confirmed and can be reviewed by the applicant.","A permitted cancellation or time change is recorded without inconsistent reservation facts."]}]}', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling-micro-app:counselingoperations', 'Approved', '0.1.0');
VALUES('re-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling-micro-app:mycounseling-episode-spec', 1, 'maro2', 1790920386197, 'maro2', 1790920350301, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"An authenticated applicant submits and monitors a counseling request, reviews the confirmed appointment, or cancels the request when permitted.","businessPurpose":"Allow an applicant to manage one active counseling request and confirm the assigned operator and appointment time without exposing internal coordination information.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"An authenticated applicant needs to submit a counseling request or review the status of an existing request.","businessSubject":"The applicant''s own counseling request","endConditions":["The applicant can review the current request status and confirmed appointment when available.","A permitted cancellation is recorded with its reason and any confirmed appointment is released."]},"stakeholders":[{"key":"applicant","name":"Applicant","role":"Applicant using self-service counseling request management","goals":["Submit and monitor the applicant''s own counseling request through confirmation or permitted cancellation."],"protectedInterests":["Privacy of the applicant''s request and internal coordination information"]}],"acts":[{"key":"applicant","name":"applicant","stakeholderKey":"applicant","responsibility":"Submit and monitor the applicant''s own counseling request through confirmation or permitted cancellation."}],"useCases":[{"key":"counseling-request-management","name":"counseling-request-management","actKey":"applicant","userGoal":"Submit a counseling request, monitor its processing status, review the confirmed appointment, and cancel the request when the applicant no longer needs counseling.","trigger":"The applicant needs counseling or returns to review an existing request.","endConditions":["The request is submitted without an active duplicate, or the existing request is displayed.","The applicant can review the confirmed appointment when one exists.","A permitted cancellation records a reason and releases any confirmed appointment once."],"capabilityNeeds":[{"key":"counseling-request-management-submit-counseling-request-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"submit-counseling-request","businessPurpose":"Submit a valid counseling request without creating an active duplicate.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-management-view-own-counseling-request-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"view-own-counseling-request","businessPurpose":"View the applicant''s permitted request status and confirmed appointment information.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"counseling-request-management-cancel-counseling-request-need","providerMicroserviceCode":"counseling","requiredCapabilityKey":"cancel-counseling-request","businessPurpose":"Cancel the applicant''s request when permitted and preserve the cancellation result.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[],"dramaParticipations":[{"key":"applicant-counseling-participation","microserviceCode":"counseling","stakeholderKey":"applicant","dramaRoleKey":"applicant","accessPurpose":"Submit and monitor the applicant''s own counseling request through confirmation or permitted cancellation.","accessConditions":["The applicant may access only the applicant''s own request and permitted disclosure."]}],"contexts":[{"key":"applicant-request-context","name":"Applicant Request Context","description":"The request information and applicant-visible status or confirmed appointment information used during self-service.","source":"Document EP-AP and UC-AP-01"}],"eventReactions":null,"policies":[{"key":"applicant-active-request","category":"Usage","name":"Active Request Handling","statement":"When an active request exists, the applicant should review that request rather than create another active request."},{"key":"applicant-disclosure","category":"Disclosure","name":"Applicant Disclosure","statement":"Candidate times, internal contact notes, and operator account identifiers are not shown in the applicant experience."}],"acceptanceCriteria":[{"key":"applicant-submit","statement":"The applicant can submit a valid counseling request with required consent without creating an active duplicate."},{"key":"applicant-review","statement":"The applicant can review permitted status, displayed responsible operator name, and confirmed appointment information."},{"key":"applicant-cancel","statement":"The applicant can cancel when permitted with a required reason, and the cancellation result is preserved."},{"key":"applicant-access","statement":"The applicant cannot access another applicant''s request or internal coordination information."}],"openIssues":[],"summaryUseCases":[{"key":"applicant-counseling-journey","goal":"Submit and monitor the applicant''s own counseling request through confirmation or permitted cancellation.","preconditions":["The applicant is authenticated.","For new submission, no active request exists, or the existing active request is shown instead."],"steps":[{"key":"submit-or-review","roleKey":"applicant","description":"The applicant submits a request or reviews the applicant''s existing request.","useCaseKey":"counseling-request-management","externalWork":null,"nextSteps":[]}],"successResults":["The applicant can review the request status and confirmed appointment when available, or a permitted cancellation is recorded."]}]}', 're-target-system:counselinglatest-architecture:1.0-bc:counselinglatest-application:counseling-micro-app:mycounseling', 'Approved', '0.1.0');
